const ENDS_AT = Date.parse('2027-01-01T04:59:00.000Z'); // 31 Dec 2026, 11:59 PM America/New_York
const END_LABEL = 'Dec 31, 2026';
const isOpen = (now = Date.now()) => now < ENDS_AT;

function sameOriginPost(request) {
  const host = new URL(request.url).hostname.toLowerCase().replace(/\.$/, '');
  const ok = (value) => {
    try { const u = new URL(value); return u.protocol === 'https:' && u.hostname.toLowerCase().replace(/\.$/, '') === host; }
    catch { return false; }
  };
  const origin = (request.headers.get('Origin') || '').trim();
  const referer = (request.headers.get('Referer') || '').trim();
  if (origin) return origin !== 'null' && ok(origin);
  if (referer) return ok(referer);
  return false;
}

function publicStatus(count, now = Date.now()) {
  return { open: isOpen(now), count: Math.max(0, Number(count) || 0), endsAt: new Date(ENDS_AT).toISOString(), endLabel: END_LABEL };
}

const hits = new Map();
const enc = new TextEncoder();
const hex = b => [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join('');
async function sha256(s) { return hex(await crypto.subtle.digest('SHA-256', enc.encode(s))); }
// Per-IP 5 / 10 min (hard). Site-wide 500 / 10 min; the site-wide cap fails open on KV errors so ordinary bidders are not locked out. IP is hashed for the KV key only and is never stored on an offer.
// Per-IP cap (5/10min) is what keeps one visitor from filling the shared 500 cap.
const MAX_PER_IP = 5, MAX_GLOBAL = 500;
async function rateLimited(env, request) {
  // Per-IP 5/10min is hard. Site-wide 500/10min is a real cap (429 once g >= 500).
  // Fail open ONLY when a KV read or write throws.
  // Accepted: KV get-then-put on rl:g: and on meta is not atomic; two concurrent
  // requests can both pass the cap check and both write. We are not adding a
  // Durable Object this round.
  const windowSec = 600;
  const bucket = 'rl:g:' + Math.floor(Date.now() / 1000 / windowSec);
  let g = 0;
  try { g = Number(await env.BIDS.get(bucket)) || 0; } catch { return false; }
  if (g >= MAX_GLOBAL) return true;
  const ip = (request.headers.get('CF-Connecting-IP') || (request.headers.get('X-Forwarded-For') || '').split(',')[0].trim() || 'unknown');
  const ipKey = 'rl:i:' + await sha256(ip);
  let n = 0;
  try { n = Number(await env.BIDS.get(ipKey)) || 0; } catch { return false; }
  if (n >= MAX_PER_IP) return true;
  try {
    await env.BIDS.put(ipKey, String(n + 1), { expirationTtl: windowSec });
    await env.BIDS.put(bucket, String(g + 1), { expirationTtl: windowSec });
  } catch { return false; }
  return false;
}
async function loadMeta(env) {
  const meta = await env.BIDS.get('meta', { type: 'json' });
  if (meta && typeof meta === 'object') return { count: Math.max(0, Number(meta.count) || 0), ids: Array.isArray(meta.ids) ? meta.ids : [] };
  return { count: 0, ids: [] };
}
function clean(s, max) { return String(s ?? '').replace(/[\u0000-\u001f\u007f]/g, '').trim().slice(0, max); }
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const CURRENCY_RE = /^[A-Za-z0-9][A-Za-z0-9 ._-]{0,15}$/;

function validateOffer(input) {
  if (!input || typeof input !== 'object') return { ok: false, error: 'Please fill in the form.' };
  const honey = clean(input.website ?? input.company ?? input.hp, 200);
  if (honey) return { ok: true, ignore: true };
  const alias = clean(input.alias ?? input.name, 80);
  const email = clean(input.email, 254).toLowerCase();
  const type = clean(input.type, 16).toLowerCase();
  const message = clean(input.message, 1000);
  if (!alias) return { ok: false, error: 'Please add a name or alias.' };
  if (!email || email.length > 254 || !EMAIL_RE.test(email)) return { ok: false, error: 'Please add a valid email.' };
  if (type !== 'money' && type !== 'item') return { ok: false, error: 'Choose Money or Physical item.' };
  const offer = { alias, email, type, time: new Date().toISOString() };
  if (message) offer.message = message;
  if (type === 'money') {
    const currency = clean(input.currency, 16);
    const raw = clean(input.amount, 32).replace(/,/g, '');
    const amount = Number(raw);
    if (!raw || !Number.isFinite(amount) || amount <= 0 || amount >= 1e15) return { ok: false, error: 'Please add an amount greater than zero.' };
    if (!currency || !CURRENCY_RE.test(currency)) return { ok: false, error: 'Please add a currency (an ISO code or another code such as BTC).' };
    offer.amount = String(raw); offer.currency = currency;
  } else {
    const item = clean(input.item ?? input.description, 500);
    if (!item) return { ok: false, error: 'Please describe the item (up to 500 characters).' };
    if (String(input.item ?? input.description ?? '').replace(/[\u0000-\u001f\u007f]/g, '').trim().length > 500) return { ok: false, error: 'Please keep the item description to 500 characters.' };
    offer.item = item;
  }
  if (String(input.message ?? '').replace(/[\u0000-\u001f\u007f]/g, '').trim().length > 1000) return { ok: false, error: 'Please keep the message to 1,000 characters.' };
  return { ok: true, offer };
}

const SEC = { 'Cache-Control': 'no-store', 'Referrer-Policy': 'no-referrer', 'X-Content-Type-Options': 'nosniff', 'X-Robots-Tag': 'noindex, nofollow, noarchive', 'Strict-Transport-Security': 'max-age=31536000' };
function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), { status, headers: { 'Content-Type': 'application/json; charset=utf-8', ...SEC } });
}
function plain(status, text, extra = {}) {
  return new Response(text, { status, headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff', 'X-Robots-Tag': 'noindex, nofollow, noarchive', 'Strict-Transport-Security': 'max-age=31536000', ...extra } });
}

async function readBody(request) {
  const ct = (request.headers.get('Content-Type') || '').toLowerCase();
  const text = await request.text();
  if (text.length > 8192) return null;
  if (ct.includes('application/json')) { try { return JSON.parse(text); } catch { return null; } }
  try { return Object.fromEntries(new URLSearchParams(text)); } catch { return null; }
}

async function handleBid(request, env) {
  if (request.method === 'GET' || request.method === 'HEAD') {
    const meta = env.BIDS ? await loadMeta(env) : { count: 0 };
    const r = json(publicStatus(meta.count));
    return request.method === 'HEAD' ? new Response(null, r) : r;
  }
  if (request.method !== 'POST') return plain(405, 'Method not allowed', { Allow: 'GET, HEAD, POST' });
  if (!sameOriginPost(request)) return json({ ok: false, error: 'That offer could not be saved.' }, 403);
  if (!env.BIDS) return json({ ok: false, error: 'That offer could not be saved.' }, 503);
  if (!isOpen()) return json({ ok: false, closed: true, error: 'Bidding closed' }, 410);
  const input = await readBody(request);
  const v = validateOffer(input);
  if (!v.ok) return json({ ok: false, error: v.error }, 400);
  if (v.ignore) { const m = await loadMeta(env); return json({ ok: true, count: m.count, endLabel: END_LABEL }); }
  if (await rateLimited(env, request)) return json({ ok: false, error: 'Too many offers right now. Please try again later.' }, 429);
  const id = `o:${Date.now()}:${crypto.randomUUID()}`;
  await env.BIDS.put(id, JSON.stringify(v.offer));
  const meta = await loadMeta(env);
  if (!meta.ids.includes(id)) meta.ids.push(id);
  meta.count = meta.ids.length;
  await env.BIDS.put('meta', JSON.stringify(meta));
  return json({ ok: true, count: meta.count, endLabel: END_LABEL });
}

